    if supply < 18:
        bid = min(my_status['budget'], max(avg_opp_bid * 1.05, DAILY_SALARY * 1.1))
    else:
        bid = min(my_status['budget'], max(avg_opp_bid * 0.9, DAILY_SALARY * 0.6))

    if my_status['hp'] < 3:
        bid = min(my_status['budget'], DAILY_SALARY * 1.5)

